import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in);int n=s.nextInt();Map<String,List<int[]>> ts=new HashMap<>();Map<String,List<String>> vals=new HashMap<>();for(int i=0;i<n;i++){String op=s.next();String key=s.next();if(op.equals("SET")){String v=s.next();int time=s.nextInt();ts.computeIfAbsent(key,z->new ArrayList<>()).add(new int[]{time,0});vals.computeIfAbsent(key,z->new ArrayList<>()).add(v);}else{int time=s.nextInt();List<int[]> times=ts.get(key);if(times==null){System.out.println("EMPTY");continue;}int l=0,r=times.size();while(l<r){int m=(l+r)/2;if(times.get(m)[0]<=time)l=m+1;else r=m;}System.out.println(l==0?"EMPTY":vals.get(key).get(l-1));}}
  }
}

