import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in);String str=s.next();String p=s.next();int k=s.nextInt();int[] rem=new int[k];for(int i=0;i<k;i++)rem[i]=s.nextInt();int l=0,r=k;while(l<r){int mid=(l+r+1)/2;boolean[] bad=new boolean[str.length()];for(int i=0;i<mid;i++)bad[rem[i]]=true;int j=0;for(int i=0;i<str.length()&&j<p.length();i++)if(!bad[i]&&str.charAt(i)==p.charAt(j))j++;if(j==p.length())l=mid;else r=mid-1;}System.out.println(l);
  }
}
